import 'package:flutter/material.dart';import '../models/user.dart';import '../services/api.dart';import 'home.dart';
class Register extends StatefulWidget{const Register({super.key});@override State<Register> createState()=>_RegisterState();}
class _RegisterState extends State<Register>{final n=TextEditingController(),e=TextEditingController(),p=TextEditingController();bool loading=false;@override void dispose(){n.dispose();e.dispose();p.dispose();super.dispose();}Future<void>go()async{setState(()=>loading=true);try{final r=await Api.post('/auth/register',{'name':n.text.trim(),'email':e.text.trim(),'password':p.text});await Api.save(r);if(!mounted)return;Navigator.pushAndRemoveUntil(context,MaterialPageRoute(builder:(_)=>Home(user:User.fromJson(Map<String,dynamic>.from(r['user'])))),(_)=>false);}catch(x){if(mounted)ScaffoldMessenger.of(context).showSnackBar(SnackBar(content:Text('$x'.replaceFirst('Exception: ',''))));}finally{if(mounted)setState(()=>loading=false);}}@override Widget build(BuildContext c)=>Scaffold(appBar:AppBar(title:const Text('Create student account')),body:ListView(padding:const EdgeInsets.all(22),children:[const SizedBox(height:18),const Text('Join CampusMate',style:TextStyle(fontSize:30,fontWeight:FontWeight.w900)),const SizedBox(height:8),const Text('Create your student identity and start exploring.'),const SizedBox(height:28),TextField(controller:n,decoration:const InputDecoration(labelText:'Full name',prefixIcon:Icon(Icons.person_outline))),const SizedBox(height:12),TextField(controller:e,decoration:const InputDecoration(labelText:'Email',prefixIcon:Icon(Icons.mail_outline))),const SizedBox(height:12),TextField(controller:p,obscureText:true,decoration:const InputDecoration(labelText:'Password (6+ characters)',prefixIcon:Icon(Icons.lock_outline))),const SizedBox(height:22),SizedBox(height:54,child:FilledButton(onPressed:loading?null:go,child:loading?const CircularProgressIndicator():const Text('Create account')))]));}
